h,w=17,30
g=[[0]*w for _ in range(h)]
# Repeated 5x5 colored motif, aligned to the topmost motif's row (row 2).
shape=["11111","00100","01110","11111","00100"]
for color,left in [(3,2),(1,9),(4,14),(8,21)]:
    for dr,line in enumerate(shape):
        for dc,ch in enumerate(line):
            if ch=='1': g[2+dr][left+dc]=color
assert len(g)==17 and all(len(r)==30 for r in g)
print(__import__('json').dumps(g,separators=(',',':')))

